const fetch = require('node-fetch');
const url = 'https://api.openweathermap.org/data/2.5/weather?q='+$location+'&appid=8786d4e1b98051572d4c349d2e16bb34&units=imperial';
const options = {
    method: 'GET',
    headers: {
        'Content-Type': 'application/json'
    }
};
try {
    const response = await fetch(url, options);
    const text = await response.text();
    return text;
} catch (error) {
    console.error(error);
    return '';
}
